    record Employee(String id, Optional<String> managerId, String email) {}

    /** The manager's normalised email, or empty when any step is missing. */
    static Optional<String> managerEmail(Map<String, Employee> byId, String employeeId) {
        return Optional.ofNullable(byId.get(employeeId))
            .flatMap(Employee::managerId)
            .map(byId::get)
            .map(Employee::email)
            .map(String::strip)
            .filter(e -> !e.isEmpty())
            .map(e -> e.toLowerCase(Locale.ROOT));
    }

    /** As managerEmail, but empty throws NoSuchElementException naming the employee. */
    static String approverEmail(Map<String, Employee> byId, String employeeId) {
        return managerEmail(byId, employeeId).orElseThrow(() -> new NoSuchElementException("no approver for " + employeeId));
    }

    static Map<String, Employee> staff() {
        var m = new HashMap<String, Employee>();
        m.put("ana", new Employee("ana", Optional.of("bo"), "ana@corp.io"));
