        m.put("di", new Employee("di", Optional.of("ed"), "di@corp.io"));
        m.put("ed", new Employee("ed", Optional.empty(), "   "));
        return m;
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("the happy path normalises the email", () -> eq(managerEmail(staff(), "ana"), Optional.of("bo@corp.io")));
